create extension if not exists pgcrypto;
create type public.app_role as enum ('user','admin');
create type public.consumption_unit as enum ('g','kg','ml','l','unidade','porção');
create type public.goal_type as enum ('emagrecimento','manutenção','ganho');

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, birth_date date, biological_sex text, height_cm numeric(6,2), role public.app_role not null default 'user', onboarding_completed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_goals (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, goal_type public.goal_type not null default 'manutenção', current_weight_kg numeric(7,3), target_weight_kg numeric(7,3), activity_level text, calories numeric(10,3) not null check(calories >= 0), protein numeric(10,3) not null check(protein >= 0), carbs numeric(10,3) not null check(carbs >= 0), fat numeric(10,3) not null check(fat >= 0), fiber numeric(10,3) not null check(fiber >= 0), water_ml numeric(10,3) not null check(water_ml >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_preferences (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, weight_unit text not null default 'kg', timezone text not null default 'America/Sao_Paulo', theme text not null default 'system', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.foods (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, name text not null, brand text, description text, category text, photo_url text, barcode text, nutrition_source text, base_unit text not null check(base_unit in ('g','ml')), calories numeric(12,5) not null check(calories>=0), protein numeric(12,5) not null check(protein>=0), carbs numeric(12,5) not null check(carbs>=0), fat numeric(12,5) not null check(fat>=0), fiber numeric(12,5) not null check(fiber>=0), saturated_fat numeric(12,5), sugar numeric(12,5), sodium numeric(12,5), default_unit public.consumption_unit not null default 'g', unit_weight_g numeric(12,5), portion_weight_g numeric(12,5), is_active boolean not null default true, is_public boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(default_unit <> 'unidade' or unit_weight_g is not null), check(default_unit <> 'porção' or portion_weight_g is not null));
create table public.food_portions (id uuid primary key default gen_random_uuid(), food_id uuid not null references public.foods(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, label text not null, grams numeric(12,5) not null check(grams>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.food_favorites (user_id uuid not null references public.profiles(id) on delete cascade, food_id uuid not null references public.foods(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id, food_id));
create table public.meal_types (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete cascade, name text not null, position smallint not null default 0, is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.daily_meals (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, meal_type_id uuid references public.meal_types(id) on delete set null, meal_date date not null, name_snapshot text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.meal_items (id uuid primary key default gen_random_uuid(), meal_id uuid not null references public.daily_meals(id) on delete cascade, food_id uuid references public.foods(id) on delete set null, user_id uuid not null references public.profiles(id) on delete cascade, food_name_snapshot text not null, calories numeric(12,5) not null, protein numeric(12,5) not null, carbs numeric(12,5) not null, fat numeric(12,5) not null, fiber numeric(12,5) not null, saturated_fat numeric(12,5), sugar numeric(12,5), sodium numeric(12,5), unit_weight_g_snapshot numeric(12,5), quantity numeric(12,5) not null check(quantity>0), unit public.consumption_unit not null, consumed_grams numeric(12,5) not null check(consumed_grams>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.recipes (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null, description text, photo_url text, category text, preparation_minutes integer, servings numeric(10,3) not null check(servings>0), instructions text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.recipe_items (id uuid primary key default gen_random_uuid(), recipe_id uuid not null references public.recipes(id) on delete cascade, food_id uuid references public.foods(id) on delete set null, user_id uuid not null references public.profiles(id) on delete cascade, quantity numeric(12,5) not null, unit public.consumption_unit not null, nutrition_snapshot jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.water_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, amount_ml numeric(10,3) not null check(amount_ml>0), logged_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.weight_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, logged_on date not null, weight_kg numeric(7,3) not null check(weight_kg>0), body_fat_percentage numeric(5,2), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.body_measurements (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, measured_on date not null, abdomen_cm numeric(7,2), waist_cm numeric(7,2), hip_cm numeric(7,2), chest_cm numeric(7,2), arm_cm numeric(7,2), thigh_cm numeric(7,2), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.daily_notes (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, note_date date not null, content text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,note_date));
create table public.audit_logs (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, action text not null, entity text not null, entity_id uuid, metadata jsonb, created_at timestamptz not null default now());
create index on public.foods(user_id); create index on public.daily_meals(user_id, meal_date); create index on public.meal_items(user_id); create index on public.water_logs(user_id, logged_at); create index on public.weight_logs(user_id, logged_on); create index on public.body_measurements(user_id, measured_on);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); insert into public.user_goals(user_id,calories,protein,carbs,fat,fiber,water_ml) values(new.id,2000,120,250,65,30,2500); insert into public.user_preferences(user_id) values(new.id); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;
create policy "read own profile" on public.profiles for select using (id = auth.uid());
create policy "update own profile" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
do $$ declare t text; begin foreach t in array array['user_goals','user_preferences','food_portions','food_favorites','meal_types','daily_meals','meal_items','recipes','recipe_items','water_logs','weight_logs','body_measurements','daily_notes','audit_logs'] loop execute format('alter table public.%I enable row level security', t); execute format('create policy "own rows" on public.%I for all using (user_id = auth.uid()) with check (user_id = auth.uid())', t); end loop; end $$;
alter table public.foods enable row level security;
create policy "read public or own foods" on public.foods for select using (is_public or user_id=auth.uid());
create policy "insert own foods" on public.foods for insert with check (user_id=auth.uid() and not is_public);
create policy "update own or admin global foods" on public.foods for update using (user_id=auth.uid() or (is_public and public.is_admin())) with check (user_id=auth.uid() or public.is_admin());
create policy "delete own or admin global foods" on public.foods for delete using (user_id=auth.uid() or (is_public and public.is_admin()));
create policy "read shared meal types" on public.meal_types for select using (user_id=auth.uid() or (is_default and user_id is null));
do $$ declare t text; begin foreach t in array array['profiles','user_goals','user_preferences','foods','food_portions','meal_types','daily_meals','meal_items','recipes','recipe_items','water_logs','weight_logs','body_measurements','daily_notes'] loop execute format('create trigger %I_updated before update on public.%I for each row execute procedure public.set_updated_at()',t,t); end loop; end $$;
